<?php
// Phase 4 API integration tests (groups, registrations, sub-trips, suppliers, bookings, forms, documents, library, roles).
declare(strict_types=1);
$base = rtrim($argv[1] ?? 'http://127.0.0.1:8000', '/') . '/api'; $results = []; $jars = []; $tok = [];
$cfg = require getenv('LTI_CONFIG'); $pdo = new PDO("mysql:host={$cfg['db']['host']};dbname={$cfg['db']['name']};charset=utf8mb4", $cfg['db']['user'], $cfg['db']['pass'], [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]);
$q = function ($sql) use ($pdo) { return $pdo->query($sql)->fetchAll(PDO::FETCH_ASSOC); }; $one = function ($sql) use ($q) { $r = $q($sql); return $r ? array_values($r[0])[0] : null; };
function req(string $who, string $method, string $path, $body = null, bool $raw = false): array { global $base, $jars, $tok; $jars[$who] = $jars[$who] ?? tempnam(sys_get_temp_dir(), 'jar');
  $ch = curl_init($base . $path); $h = ['Accept: application/json']; if (!empty($tok[$who]) && $method !== 'GET') $h[] = 'X-CSRF-Token: ' . $tok[$who];
  if (is_array($body) && isset($body['__multipart'])) { unset($body['__multipart']); curl_setopt($ch, CURLOPT_POSTFIELDS, $body); } elseif ($body !== null) { $h[] = 'Content-Type: application/json'; curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode($body)); }
  curl_setopt_array($ch, [CURLOPT_CUSTOMREQUEST => $method, CURLOPT_RETURNTRANSFER => true, CURLOPT_HTTPHEADER => $h, CURLOPT_COOKIEJAR => $jars[$who], CURLOPT_COOKIEFILE => $jars[$who]]);
  $res = curl_exec($ch); $c = curl_getinfo($ch, CURLINFO_HTTP_CODE); $ct = (string)curl_getinfo($ch, CURLINFO_CONTENT_TYPE); curl_close($ch); return [$c, $raw ? $res : (json_decode((string)$res, true) ?? []), $ct]; }
function login(string $who, string $email): void { global $tok; [$c, $d] = req($who, 'POST', '/auth/login', ['email' => $email, 'password' => 'Dev-Password-2026']); if ($c !== 200) throw new Exception("login $email $c"); $tok[$who] = $d['csrf']; }
function t(string $n, callable $f): void { global $results; try { $results[] = [$n, true, (string)$f()]; } catch (Throwable $e) { $results[] = [$n, false, $e->getMessage()]; } }
function ok($c, string $m): void { if (!$c) throw new Exception($m); }
foreach (['own' => 'owner@lti.test', 'adm' => 'admin@lti.test', 'adv' => 'advisor@lti.test', 'adv2' => 'advisor2@lti.test', 'fin' => 'finance@lti.test', 'sal' => 'sales@lti.test', 'ops' => 'ops@lti.test', 'trv' => 'traveler@lti.test'] as $k => $e) login($k, $e);
$amelia = (int)$one("SELECT id FROM contacts WHERE email='amelia@example.com'"); $shah = (int)$one("SELECT id FROM contacts WHERE email='shah@example.com'"); $bell = (int)$one("SELECT id FROM contacts WHERE email='marcus.bell@example.com'");
$amalfi = (int)$one("SELECT id FROM trips WHERE name='Amalfi Coast Anniversary'"); $advId = (int)$one("SELECT id FROM users WHERE email='advisor@lti.test'");
$S = [];
// ---------------- Groups ----------------
t('TC01 Create group trip; MySQL record has group fields', function () use (&$S, $advId, $one) { [$c, $d] = req('own', 'POST', '/groups', ['name' => 'Danube Christmas Markets 2027', 'destination' => 'Budapest to Passau', 'startDate' => '2027-12-10', 'endDate' => '2027-12-18', 'capacity' => 3, 'registrationDeadline' => '2027-11-20', 'coordinatorId' => $advId, 'status' => 'Open', 'details' => ['headline' => 'Sparkle along the Danube', 'depositPerPerson' => 500]]);
  ok($c === 201, "create $c " . json_encode($d)); $S['g'] = $d['group']['id']; $r = $one("SELECT CONCAT_WS('|',trip_type,group_capacity,registration_deadline,coordinator_id,status) FROM trips WHERE id={$S['g']}");
  ok($r === "group|3|2027-11-20|$advId|Open", $r); return "group {$S['g']}: $r"; });
t('TC02 Edit group; persists; stale version 409; deadline after departure 422', function () use (&$S, $one) { [, $g] = req('own', 'GET', "/groups/{$S['g']}"); $v = $g['group']['version'];
  [$c] = req('own', 'PUT', "/groups/{$S['g']}", ['name' => 'Danube Christmas Markets 2027 — LTI Group', 'capacity' => 3, 'version' => $v]); [$c2] = req('own', 'PUT', "/groups/{$S['g']}", ['name' => 'x', 'version' => $v]);
  [$c3] = req('own', 'PUT', "/groups/{$S['g']}", ['registrationDeadline' => '2028-01-01']); [$c4] = req('own', 'PUT', "/groups/{$S['g']}/rooms", ['rooms' => [['name' => 'Veranda double', 'pricePerPerson' => 4295, 'capacity' => 2], ['name' => 'Single', 'pricePerPerson' => 6495, 'capacity' => 1]]]);
  ok($c === 200 && $c2 === 409 && $c3 === 422 && $c4 === 200 && $one("SELECT name FROM trips WHERE id={$S['g']}") === 'Danube Christmas Markets 2027 — LTI Group' && (int)$one("SELECT COUNT(*) FROM group_rooms WHERE trip_id={$S['g']}") === 2 && $one("SELECT CONCAT_WS('|',start_date,destination,registration_deadline) FROM trips WHERE id={$S['g']}") === '2027-12-10|Budapest to Passau|2027-11-20', "$c $c2 $c3 $c4"); return 'saved; partial update kept dates; 2 rooms'; });
t('Group itinerary editable through the itinerary API', function () use (&$S) { [, $it] = req('own', 'GET', "/trips/{$S['g']}/itinerary"); $o = $it['options'][0];
  $o['days'] = [['id' => 'n1', 't' => 'Embark in Budapest', 'acts' => [['id' => 'n2', 'type' => 'cruise', 'title' => 'AmaMagna embarkation'], ['id' => 'n3', 'type' => 'dining', 'title' => 'Welcome reception']]], ['id' => 'n4', 't' => 'Vienna', 'acts' => [['id' => 'n5', 'type' => 'tour', 'title' => 'Vienna markets walk']]]];
  [$c, $d] = req('own', 'PUT', "/trips/{$S['g']}/itinerary", ['rev' => $it['rev'], 'options' => [$o]]); ok($c === 200 && count($d['options'][0]['days']) === 2, "save $c"); return '3 group activities'; });
t('TC03 Register an existing contact: registration, sub-trip, travelers and synced itinerary', function () use (&$S, $amelia, $one) { [, $g] = req('own', 'GET', "/groups/{$S['g']}"); $room = $g['group']['rooms'][0]['id']; $S['roomD'] = $room; $S['roomS'] = $g['group']['rooms'][1]['id'];
  [$c, $d] = req('own', 'POST', "/groups/{$S['g']}/registrations", ['travelers' => [['contactId' => $amelia]], 'roomId' => $room, 'roomPreference' => 'High floor', 'specialRequests' => 'Vegetarian meals']);
  ok($c === 201 || $c === 200, "register $c " . json_encode($d)); $S['reg1'] = $d['registrationId']; $S['sub1'] = $d['subTripId'];
  $row = $one("SELECT CONCAT_WS('|',status,contact_id,room_preference,special_requests) FROM group_registrations WHERE id={$S['reg1']}"); $sub = $one("SELECT CONCAT_WS('|',trip_type,parent_trip_id) FROM trips WHERE id={$S['sub1']}");
  $acts = (int)$one("SELECT COUNT(*) FROM itinerary_activities a JOIN itinerary_days d ON d.id=a.day_id JOIN itinerary_options o ON o.id=d.option_id WHERE o.trip_id={$S['sub1']} AND a.origin_activity_id IS NOT NULL");
  ok($row === "active|$amelia|High floor|Vegetarian meals" && $sub === "sub|{$S['g']}" && $acts === 3 && (int)$one("SELECT COUNT(*) FROM trip_travelers WHERE trip_id={$S['sub1']} AND contact_id=$amelia AND permission='primary'") === 1, "$row / $sub / $acts"); return "registration {$S['reg1']}, sub-trip {$S['sub1']} with 3 synced activities"; });
t('TC04 Register a new traveler; contact is created and linked', function () use (&$S, $one) { [$c, $d] = req('own', 'POST', "/groups/{$S['g']}/registrations", ['travelers' => [['firstName' => 'Grace', 'lastName' => 'Lin', 'email' => 'grace.lin@example.com']], 'roomId' => $S['roomS']]);
  ok($c === 201 || $c === 200, "register $c " . json_encode($d)); $cid = (int)$one("SELECT id FROM contacts WHERE email='grace.lin@example.com'"); $S['grace'] = $cid; $S['reg2'] = $d['registrationId'];
  ok($cid > 0 && $one("SELECT source FROM contacts WHERE id=$cid") === 'Group registration' && (int)$one("SELECT COUNT(*) FROM group_registration_travelers WHERE registration_id={$d['registrationId']} AND contact_id=$cid") === 1, 'contact link'); return "contact $cid created"; });
t('TC05 Duplicate active registration is rejected (409)', function () use (&$S, $amelia) { [$c, $d] = req('own', 'POST', "/groups/{$S['g']}/registrations", ['travelers' => [['contactId' => $amelia]]]); ok($c === 409 && strpos($d['error'], 'Already registered') !== false, "$c " . ($d['error'] ?? '')); return $d['error']; });
t('TC06 Capacity: over-capacity refused; advisor cannot override; administrator override recorded', function () use (&$S, $shah, $bell, $one) {
  [$c1, $d1] = req('own', 'POST', "/groups/{$S['g']}/registrations", ['travelers' => [['contactId' => $shah], ['contactId' => $bell]]]);   // 2 + 2 > 3
  [$c2] = req('adv', 'POST', "/groups/{$S['g']}/registrations", ['travelers' => [['firstName' => 'Extra', 'email' => 'extra1@example.com'], ['firstName' => 'Extra2', 'email' => 'extra2@example.com']], 'overrideCapacity' => true]);
  [$c3, $d3] = req('adm', 'POST', "/groups/{$S['g']}/registrations", ['travelers' => [['contactId' => $shah], ['contactId' => $bell]], 'overrideCapacity' => true]);
  $over = $c3 === 201 || $c3 === 200 ? $one("SELECT over_capacity_by IS NOT NULL FROM group_registrations WHERE id=" . (int)$d3['registrationId']) : null;
  ok($c1 === 409 && stripos($d1['error'], 'capacity') !== false && $c2 === 409 && ($c3 === 201 || $c3 === 200) && (string)$over === '1', "$c1 $c2 $c3 over=" . var_export($over, true) . ' msg=' . ($d1['error'] ?? '')); $S['reg3'] = $d3['registrationId'];
  [$c4] = req('own', 'POST', "/groups/{$S['g']}/registrations/{$S['reg3']}/cancel", ['reason' => 'Test']); $active = (int)$one("SELECT COUNT(*) FROM group_registration_travelers grt JOIN group_registrations gr ON gr.id=grt.registration_id WHERE gr.group_trip_id={$S['g']} AND gr.status='active'");
  ok($c4 === 200 && $active === 2, "cancel $c4 active=$active"); return 'refused 409; advisor override 409; admin override flagged; cancellation frees places'; });
t('Registration update: change room and add a traveler with checks', function () use (&$S, $shah) { [$c] = req('own', 'PUT', "/groups/{$S['g']}/registrations/{$S['reg1']}", ['travelers' => [['contactId' => $S['grace']]]]);
  [$c2, $d2] = req('own', 'PUT', "/groups/{$S['g']}/registrations/{$S['reg1']}", ['roomPreference' => 'Quiet cabin', 'travelers' => [['contactId' => (int)$GLOBALS['amelia']], ['contactId' => $shah]]]);
  ok($c === 409 && $c2 === 200, "$c $c2 " . json_encode($d2['error'] ?? '')); return 'duplicate traveler 409; update 200'; });
t('TC07 Create a sub-trip manually and associate it with the group', function () use (&$S, $one) { [$c, $d] = req('own', 'POST', "/groups/{$S['g']}/subtrips", ['name' => 'Danube — staff hosts', 'startDate' => '2027-12-09', 'endDate' => '2027-12-18']);
  ok($c === 200 && $one("SELECT CONCAT_WS('|',parent_trip_id,start_date) FROM trips WHERE id=" . (int)$d['subTripId']) === "{$S['g']}|2027-12-09", "$c"); $S['sub2'] = $d['subTripId'];
  [$c2, $t] = req('own', 'PUT', "/trips/{$S['sub2']}", ['status' => 'Planning', 'endDate' => '2027-12-19']); ok($c2 === 200 && $t['trip']['tripType'] === 'sub' && $t['trip']['startDate'] === '2027-12-09' && $t['trip']['name'] === 'Danube — staff hosts', "sub edit $c2 " . json_encode($t['trip'] ?? [])); return "sub-trip {$S['sub2']} with custom dates"; });
t('TC08–TC09 Sync group itinerary into sub-trips; custom and edited sub-trip activities are preserved', function () use (&$S, $one) {
  [, $si] = req('own', 'GET', "/trips/{$S['sub1']}/itinerary"); $o = $si['options'][0];
  $o['days'][0]['acts'][] = ['id' => 'c1', 'type' => 'dining', 'title' => 'Private dinner (custom for Amelia)'];
  $o['days'][1]['acts'][0]['title'] = 'Vienna markets walk with a private guide';   // editing a synced activity detaches it
  [$cs] = req('own', 'PUT', "/trips/{$S['sub1']}/itinerary", ['rev' => $si['rev'], 'options' => [$o]]); ok($cs === 200, "sub save $cs");
  [, $gi] = req('own', 'GET', "/trips/{$S['g']}/itinerary"); $g = $gi['options'][0];
  $g['days'][0]['acts'][1]['title'] = 'Welcome reception and briefing'; $g['days'][1]['acts'][0]['title'] = 'Vienna Christmas markets walk'; $g['days'][] = ['id' => 'n9', 't' => 'Melk', 'acts' => [['id' => 'n10', 'type' => 'excursion', 'title' => 'Melk Abbey']]];
  [$cg] = req('own', 'PUT', "/trips/{$S['g']}/itinerary", ['rev' => $gi['rev'], 'options' => [$g]]); ok($cg === 200, "group save $cg");
  [$cp, $pv] = req('own', 'POST', "/groups/{$S['g']}/sync", ['apply' => false]); $p1 = null; foreach ($pv['results'] as $r) if ($r['subTripId'] == $S['sub1']) $p1 = $r;
  ok($cp === 200 && $p1['added'] === 1 && $p1['updated'] >= 1 && $p1['customKept'] === 2, 'preview ' . json_encode($p1));
  [$ca] = req('own', 'POST', "/groups/{$S['g']}/sync", ['apply' => true]);
  $titles = array_column($q = $GLOBALS['q']("SELECT a.title FROM itinerary_activities a JOIN itinerary_days d ON d.id=a.day_id JOIN itinerary_options o ON o.id=d.option_id WHERE o.trip_id={$S['sub1']} ORDER BY d.sort_order, a.sort_order"), 'title');
  ok($ca === 200 && in_array('Private dinner (custom for Amelia)', $titles, true) && in_array('Vienna markets walk with a private guide', $titles, true) && in_array('Welcome reception and briefing', $titles, true) && in_array('Melk Abbey', $titles, true) && !in_array('Vienna Christmas markets walk', $titles, true), json_encode($titles));
  $sub2 = array_column($GLOBALS['q']("SELECT a.title FROM itinerary_activities a JOIN itinerary_days d ON d.id=a.day_id JOIN itinerary_options o ON o.id=d.option_id WHERE o.trip_id={$S['sub2']}"), 'title'); ok(in_array('Vienna Christmas markets walk', $sub2, true), 'sub2 ' . json_encode($sub2));
  return 'preview ' . json_encode($p1) . '; applied: ' . implode(' > ', $titles); });
// ---------------- Suppliers ----------------
t('TC10 Create supplier; MySQL record', function () use (&$S, $one) { [$c, $d] = req('ops', 'POST', '/suppliers', ['name' => 'AmaWaterways', 'category' => 'cruise', 'email' => 'groups@amawaterways.example', 'destination' => 'European rivers', 'commissionRate' => 15, 'contractReference' => 'AMA-2027-GRP', 'isPreferred' => true]);
  ok($c === 201, "$c " . json_encode($d)); $S['sup'] = $d['supplier']['id']; ok($one("SELECT CONCAT_WS('|',category,status,commission_rate,contract_reference) FROM suppliers WHERE id={$S['sup']}") === 'cruise|active|15.00|AMA-2027-GRP', 'db');
  [$c2] = req('ops', 'POST', '/suppliers', ['name' => 'AmaWaterways', 'category' => 'cruise']); [$c3] = req('ops', 'POST', '/suppliers', ['name' => 'Bad', 'category' => 'spaceship']); ok($c2 === 409 && $c3 === 422, "$c2 $c3");
  req('ops', 'PUT', "/suppliers/{$S['sup']}/contacts", ['contacts' => [['name' => 'Group desk', 'email' => 'desk@amawaterways.example', 'isPrimary' => true]]]); return "supplier {$S['sup']}; duplicate 409; bad category 422"; });
t('TC11 Edit supplier; persists; stale version 409', function () use (&$S, $one) { [, $g] = req('ops', 'GET', "/suppliers/{$S['sup']}"); $v = $g['supplier']['version'];
  [$c] = req('ops', 'PUT', "/suppliers/{$S['sup']}", ['name' => 'AmaWaterways', 'category' => 'cruise', 'phone' => '+1 800 555 0100', 'commissionRate' => 16, 'version' => $v]); [$c2] = req('ops', 'PUT', "/suppliers/{$S['sup']}", ['name' => 'AmaWaterways', 'category' => 'cruise', 'version' => $v]);
  ok($c === 200 && $c2 === 409 && $one("SELECT commission_rate FROM suppliers WHERE id={$S['sup']}") === '16.00' && count($g['supplier']['contacts']) === 1, "$c $c2"); return 'saved'; });
// ---------------- Bookings ----------------
t('TC13 Create booking linked to an existing trip and supplier', function () use (&$S, $one) { [$c, $d] = req('own', 'POST', '/bookings', ['tripId' => $S['g'], 'supplierId' => $S['sup'], 'category' => 'cruise', 'startDate' => '2027-12-10', 'endDate' => '2027-12-17', 'amount' => 25000, 'commissionRate' => 15, 'confirmationNumber' => 'AMA-77310', 'notes' => 'Group block of 12 berths']);
  ok($c === 201, "$c " . json_encode($d)); $S['bk'] = $d['booking']['id']; $r = $one("SELECT CONCAT_WS('|',reference,trip_id,supplier_id,booking_type,status,commission_expected) FROM bookings WHERE id={$S['bk']}");
  ok(preg_match('/^B-\d{5}\|' . $S['g'] . '\|' . $S['sup'] . '\|cruise\|pending\|3750\.00$/', $r) === 1, $r); return $r; });
t('TC14 Add traveler to booking; travelers not on the trip are rejected', function () use (&$S, $amelia, $one) { [$c, $d] = req('own', 'POST', '/bookings', ['tripId' => $S['sub1'], 'supplierId' => $S['sup'], 'category' => 'transfer', 'amount' => 140]); $S['bk2'] = $d['booking']['id'];
  [$c1] = req('own', 'PUT', "/bookings/{$S['bk2']}/travelers", ['travelerIds' => [$amelia]]); [$c2] = req('own', 'PUT', "/bookings/{$S['bk2']}/travelers", ['travelerIds' => [$S['grace']]]);
  ok($c === 201 && $c1 === 200 && $c2 === 422 && (int)$one("SELECT COUNT(*) FROM booking_travelers WHERE booking_id={$S['bk2']} AND contact_id=$amelia") === 1, "$c $c1 $c2"); return 'sub-trip booking with traveler; outsider 422'; });
t('TC15 Edit and cancel booking; cancelled booking is read-only; history recorded', function () use (&$S, $one) { [, $g] = req('own', 'GET', "/bookings/{$S['bk']}");
  [$c] = req('own', 'PUT', "/bookings/{$S['bk']}", ['status' => 'confirmed', 'amount' => 26000, 'version' => $g['booking']['version']]); [$c2] = req('own', 'POST', "/bookings/{$S['bk2']}/cancel", ['reason' => 'Client changed plans']);
  [$c3] = req('own', 'PUT', "/bookings/{$S['bk2']}", ['notes' => 'x']); [, $h] = req('own', 'GET', "/bookings/{$S['bk']}"); $acts = array_column($h['booking']['history'], 'action');
  ok($c === 200 && $c2 === 200 && $c3 === 409 && $one("SELECT CONCAT(status,'|',commission_expected) FROM bookings WHERE id={$S['bk']}") === 'confirmed|3900.00' && $one("SELECT status FROM bookings WHERE id={$S['bk2']}") === 'cancelled' && $acts === ['booking.created', 'booking.confirmed'], "$c $c2 $c3 " . json_encode($acts)); return 'confirmed, commission recalculated, cancelled, history ' . implode(' > ', $acts); });
t('TC16 Invalid booking relationships are rejected', function () use (&$S, $amalfi) { [$c1] = req('own', 'POST', '/bookings', ['tripId' => 999999, 'category' => 'hotel']); [$c2] = req('own', 'POST', '/bookings', ['tripId' => $S['g'], 'supplierId' => 999999, 'category' => 'cruise']);
  [$c3] = req('adv2', 'POST', '/bookings', ['tripId' => $amalfi, 'category' => 'accommodation']); [$c4] = req('own', 'POST', '/bookings', ['tripId' => $S['g'], 'category' => 'spaceship']); [$c5] = req('own', 'POST', '/bookings', ['category' => 'cruise']);
  ok($c1 === 404 && $c2 === 422 && $c3 === 404 && $c4 === 422 && $c5 === 422, "$c1 $c2 $c3 $c4 $c5"); return 'missing trip 404, missing supplier 422, other advisor trip 404, bad category 422, no trip 422'; });
t('TC12 Archive supplier: existing bookings intact; cannot be newly assigned', function () use (&$S, $one) { [$c] = req('ops', 'POST', "/suppliers/{$S['sup']}/archive");
  [$c2] = req('own', 'POST', '/bookings', ['tripId' => $S['g'], 'supplierId' => $S['sup'], 'category' => 'cruise']); [, $b] = req('own', 'GET', "/bookings/{$S['bk']}"); [$c3] = req('own', 'PUT', "/bookings/{$S['bk']}", ['notes' => 'still editable']);
  [, $l] = req('own', 'GET', '/suppliers'); ok($c === 200 && $c2 === 422 && $b['booking']['supplierId'] === $S['sup'] && $b['booking']['supplierArchived'] === true && $c3 === 200 && !in_array($S['sup'], array_column($l['items'], 'id'), true) && $one("SELECT status FROM suppliers WHERE id={$S['sup']}") === 'archived', "$c $c2 $c3"); return 'archived; booking keeps supplier; new assignment 422'; });
// ---------------- Forms ----------------
t('TC17–TC18 Create form; add, edit and reorder fields', function () use (&$S, $one) { [$c, $d] = req('sal', 'POST', '/forms', ['name' => 'Trip inquiry 2027', 'category' => 'Lead', 'steps' => ['About you', 'Your trip'], 'settings' => ['createContact' => true, 'createTrip' => true],
  'fields' => [['key' => 'first', 'label' => 'First name', 'type' => 'text', 'required' => true], ['key' => 'email', 'label' => 'Email', 'type' => 'email', 'required' => true], ['key' => 'who', 'label' => 'Who is traveling?', 'type' => 'select', 'options' => ['Couple', 'Family'], 'step' => 2], ['key' => 'kids', 'label' => 'Children’s ages', 'type' => 'text', 'required' => true, 'showIf' => 'who=Family', 'step' => 2]]]);
  ok($c === 201, "create $c " . json_encode($d)); $S['form'] = $d['form']['id']; $f = $d['form']['fields'];
  $f[0]['label'] = 'Given name'; $f[] = ['key' => 'dest', 'label' => 'Destination', 'type' => 'text', 'step' => 2]; $f = [$f[1], $f[0], $f[2], $f[3], $f[4]];
  [$c2] = req('sal', 'PUT', "/forms/{$S['form']}", ['fields' => $f, 'version' => $d['form']['version']]); $order = array_column($GLOBALS['q']("SELECT field_key FROM form_fields WHERE form_id={$S['form']} ORDER BY sort_order"), 'field_key');
  [$c3] = req('sal', 'PUT', "/forms/{$S['form']}", ['fields' => [['label' => 'Pick', 'type' => 'select']]]);
  ok($c2 === 200 && $order === ['email', 'first', 'who', 'kids', 'dest'] && $one("SELECT label FROM form_fields WHERE form_id={$S['form']} AND field_key='first'") === 'Given name' && $c3 === 422, "$c2 " . json_encode($order) . " $c3"); return 'order ' . implode(',', $order); });
t('TC19 Publish form; public submission with required and conditional validation', function () use (&$S) { [, $f] = req('sal', 'GET', "/forms/{$S['form']}"); $tk = $f['form']['token']; $S['tk'] = $tk;
  [$c0] = req('anon', 'GET', "/public/forms/$tk"); [$c1] = req('sal', 'POST', "/forms/{$S['form']}/publish"); [$c2, $pf] = req('anon', 'GET', "/public/forms/$tk");
  [$c3, $e3] = req('anon', 'POST', "/public/forms/$tk/submit", ['answers' => ['first' => 'Nora', 'email' => 'nora.q@example.com', 'who' => 'Family']]);
  [$c4, $d4] = req('anon', 'POST', "/public/forms/$tk/submit", ['answers' => ['first' => 'Nora', 'email' => 'nora.q@example.com', 'who' => 'Family', 'kids' => '6 and 9', 'dest' => 'Kenya']]);
  [$c5] = req('anon', 'POST', "/public/forms/$tk/submit", ['answers' => ['first' => 'Leo', 'email' => 'leo@example.com', 'who' => 'Couple']]);
  ok($c0 === 404 && $c1 === 200 && $c2 === 200 && $c3 === 422 && isset($e3['fields']['kids']) && $c4 === 200 && $c5 === 200, "$c0 $c1 $c2 $c3 $c4 $c5"); $S['sub_id'] = $d4['submissionId']; return 'draft hidden; conditional required enforced; 2 submissions'; });
t('TC20 Submissions and answers in MySQL; contact and inquiry trip created; CSV export', function () use (&$S, $one) { $n = (int)$one("SELECT COUNT(*) FROM form_submissions WHERE form_id={$S['form']}"); $ans = $one("SELECT value FROM form_answers WHERE submission_id={$S['sub_id']} AND field_key='kids'");
